Rules.InvariantScript:
Clear(col_colVeiGalleryImg);
Clear(col_colVeiEnvolvidos);
Reset(cmbColVeiHoraCadastro);
Reset(cmbColVeiMinuCadastro);
Reset(TxtColVeiLocal);
Reset(ComboBoxMG1);
Reset(ComboBoxMG2);
Reset(cmbColVeiTipColisao);
Reset(TxtColVeiDescOcorrencia);
Reset(TxtColVeiDanos)

Reset(TxtColVeiNome);
Reset(TxtColVeiColete);
Reset(TxtColVeiEmpresa);
Reset(TxtColVeiCodVeiculo);
Reset(TxtColVeiEmpresaProp);
Reset(cmbColVeiCnhCompativel);
Reset(cmbColVeiBoaCondicao)

If(
    IsBlank(TxtColVeiNome.Text) = true Or IsBlank(TxtColVeiColete.Text) = true Or IsBlank(TxtColVeiEmpresa.Text) = true Or IsBlank(TxtColVeiCodVeiculo.Text) = true Or IsBlank(TxtColVeiEmpresaProp.Text) = true Or IsBlank(cmbColVeiCnhCompativel.Selected.Value) = true Or IsBlank(cmbColVeiBoaCondicao.Selected.Value) = true,
    Notify(
        "Insira os dados do envolvido selecionado!",
        NotificationType.Error
    ),
    Collect(
        col_colVeiEnvolvidos,
        {
            id: Value(
                First(
                    SortByColumns(
                        Filter(
                            col_colVeiEnvolvidos,
                            id >= 0
                        ),
                        "id",
                        SortOrder.Descending
                    )
                ).id + 1
            ),
            nome: TxtColVeiNome.Text,
            colete: TxtColVeiColete.Text,
            empresa: TxtColVeiEmpresa.Text,
            codVeiculo: TxtColVeiCodVeiculo.Text,
            empresaProp: TxtColVeiEmpresaProp.Text,
            cnhCompativel: cmbColVeiCnhCompativel.Selected.Value,
            boaCondicao: cmbColVeiBoaCondicao.Selected.Value
        }
    );
    Select(ButtonResetFormColVeiEnvolvidos)
)

If(
    IsBlank(AddMediaButtonImgCadastrar_1.Media) = false,
    Collect(
        col_colVeiGalleryImg,
        {
            id: Value(
                First(
                    SortByColumns(
                        Filter(
                            col_colVeiGalleryImg,
                            id >= 0
                        ),
                        "id",
                        SortOrder.Descending
                    )
                ).id + 1
            ),
            img: UploadedImageCadastrar_1.Image
        }
    )
);
Reset(AddMediaButtonImgCadastrar_1)

UpdateContext(
    {
        var_visibleSpiner: true,
        var_formErro: false,
        var_colVeiId: Value(Last('14.4-tbl_ColVeiculos').ID) + 1
    }
);
Switch(
    true,
    IsBlank(cmbColVeiHoraCadastro.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(cmbColVeiMinuCadastro.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtColVeiLocal.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(ComboBoxMG1.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(ComboBoxMG2.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(cmbColVeiTipColisao.Selected.Value) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtColVeiDescOcorrencia.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtColVeiDanos.Text) = true,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    CountRows(col_colVeiGalleryImg) = 0,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    CountRows(col_colVeiEnvolvidos) = 0,
    UpdateContext(
        {
            var_formErro: true,
            varBordaDefault: Color.Red
        }
    ),
    UpdateContext({var_formErro: false})
);
If(
    var_formErro = true,
    Notify(
        "Atenção todas as informações devem ser preenchidas!",
        NotificationType.Error
    ),
    //Insert de dados no database------------------------------------------------------------------------------
    Patch(
        '14.4-tbl_ColVeiculos',
        Defaults('14.4-tbl_ColVeiculos'),
        {
            colVei_id: var_colVeiId,
            colVei_data: dtpColVeiDataCadastro.SelectedDate,
            colVei_hora: cmbColVeiHoraCadastro.Selected.Value & ":" & cmbColVeiMinuCadastro.Selected.Value,
            colVei_local: TxtColVeiLocal.Text,
            colVei_mapaGrade: ComboBoxMG1.Selected.Value&"-"&ComboBoxMG2.Selected.Value,
            colVei_tipoColisao: cmbColVeiTipColisao.Selected.Value,
            colVei_descOcorrencia: TxtColVeiDescOcorrencia.Text,
            colVei_danos: TxtColVeiDanos.Text,
            colVei_bloco: varBlocoUser,
            colVei_aeroporto: varAeroUser
        }
    );
    //insert dos envolvidos
ForAll(
        col_colVeiEnvolvidos,
        Patch(
            '14.4-tbl_ColVeiculosEnvolvidos',
            Defaults('14.4-tbl_ColVeiculosEnvolvidos'),
            {
                colVeiEnv_idOcorrencia: var_colVeiId,
                colVeiEnv_nome: nome,
                colVeiEnv_colete: colete,
                colVeiEnv_empresa: empresa,
                colVeiEnv_codVeiculo: codVeiculo,
                colVeiEnv_empresaProp: empresaProp,
                colVeiEnv_cnhComp: cnhCompativel,
                colVeiEnv_boaCondicoes: boaCondicao
            }
        )
    );
    //insert das imagens
ForAll(
        col_colVeiGalleryImg,
        Patch(
            '14.4-tbl_ColVeiculosImg',
            Defaults('14.4-tbl_ColVeiculosImg'),
            {
                colVeiImg_idOcorrencia: var_colVeiId,
                colVeiImg_imagem: img
            }
        )
    );

If(
        varPerfilUser = "Sede",
        ClearCollect(
            col_colVeiRegistros,
            Sort(
                '14.4-tbl_ColVeiculos',
                colVei_id,
                SortOrder.Descending
            )
        ),
        ClearCollect(
            col_colVeiRegistros,
            Sort(
                Filter(
                    '14.4-tbl_ColVeiculos',
                    colVei_aeroporto = varAeroUser
                ),
                colVei_id,
                SortOrder.Descending
            )
        )
    );
    Select(ButtonResetFormColVei);
    Navigate(
        ScreenSucesso,
        ScreenTransition.Fade,
        {var_navigateSucess: ScreenColisaoVeiculos}
    )
);
UpdateContext({var_visibleSpiner: false})
